#include <stdio.h>

int main() {
    int a[] = {2, 6, 9};
    int b[] = {1, 3, 4, 8};
    int merged[7];
    int i = 0, j = 0, k = 0;
    while (i < 3 && j < 4) {
        merged[k++] = a[i] <= b[j] ? a[i++] : b[j++];
    }
    while (i < 3) merged[k++] = a[i++];
    while (j < 4) merged[k++] = b[j++];
    for (int x = 0; x < 7; x++) printf("%d ", merged[x]);
    printf("\n");
    return 0;
}
